(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzg-sj-prepa-med-j10-sf3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzg-sj-prepa-med-j10-sf3\",\n \"titre\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 56,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J10_Medecine_SF3_corrige_explique.pdf\",\n   \"sha256\": \"8907cbe2f3b0c08c567f1d2854ba037e890e14c5eade90376bf735c60885556f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Médecine · Prépa D.E J10 (SF3)\",\n     \"slug\": \"prepa-med-j10-sf3\",\n     \"pages\": \"\",\n     \"count\": 56,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Médecine\",\n     \"source\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quels sont les quatre examens complémentaires nécessaires au diagnostic médical de la fièvre typhoïde parmi les suivants ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hémoculture\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"NFS-VS\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Coproculture\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Albumine/Sucre\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Myéloculture\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Sérologie de Widal et Félix\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Hémoculture ; C. Coproculture ; E. Myéloculture ; F. Sérologie de Widal et Félix\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"L’hémoculture est l’examen de certitude (positive dans plus de 90 % des cas au 1er septénaire) ; la coproculture confirme en période de diarrhée et dépiste le portage chronique ; le sérodiagnostic de Widal et Félix recherche les anticorps anti-O et anti-H. La myéloculture (culture de la moelle) est une autre culture du germe. La NFS-VS n’est qu’un examen d’orientation (leuconeutropénie) et albumine/sucre n’a pas d’intérêt ici. Remarque : la myéloculture n’est pas citée dans les cours du projet (connaissance générale) ; elle est retenue par la correction nationale.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Fièvre typhoïde – III. Biologie ; Cours de maladies infectieuses – Soins infirmiers en maladies infectieuses, Fièvre typhoïde – V. La biologie.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Relevez quatre complications possibles de la fièvre typhoïde parmi les suivantes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hémorragie digestive\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Amaigrissement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Perforation intestinale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Mort\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Péritonite\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Choc septique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Hémorragie digestive ; C. Perforation intestinale ; E. Péritonite ; F. Choc septique\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Les complications du 3e septénaire font la gravité de la maladie : hémorragies digestives (mélaena, rectorragie), perforation intestinale responsable d’une péritonite, collapsus cardio-vasculaire (choc). La mort est une issue et non une complication ; l’amaigrissement est un signe banal.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Fièvre typhoïde – 2.4 Les complications ; Cours de maladies infectieuses – Soins infirmiers en maladies infectieuses, Fièvre typhoïde – IV.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quels sont les quatre signes d'alerte d'une dengue sévère parmi les suivants ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Douleurs abdominales intenses\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Vomissements persistants\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Raideur méningée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Saignements muqueux\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Céphalée en casque\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Léthargie ou agitation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Douleurs abdominales intenses ; B. Vomissements persistants ; D. Saignements muqueux ; F. Léthargie ou agitation\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Les signes d’alerte annoncent le passage à la dengue sévère (hémorragique ou avec choc) : douleurs abdominales intenses, vomissements persistants, saignements des muqueuses (gencives, nez), léthargie ou agitation. La raideur méningée et la céphalée en casque évoquent une méningite.\\n\\nSource : Cours de maladies infectieuses – Soins infirmiers en maladies infectieuses, Dengue – complications (douleurs abdominales, hémorragies, choc) ; liste OMS des signes d’alerte (explication partiellement hors cours du projet).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Retrouvez deux mesures de prévention communautaire de la dengue parmi les propositions suivantes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Destruction des gîtes larvaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hygiène corporelle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Protection contre les piqûres de moustiques\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Vaccination systématique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Destruction des gîtes larvaires ; C. Protection contre les piqûres de moustiques\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"La prévention repose sur la lutte antivectorielle : destruction et élimination des gîtes larvaires (pneus, boîtes de conserve) et protection contre les piqûres (moustiquaires imprégnées, répulsifs, vêtements longs). L’hygiène corporelle ne joue aucun rôle et il n’existe pas de vaccination systématique selon le cours.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), La Dengue – V. Prise en charge et VI. Prévention.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est le principal mode de transmission de la fièvre typhoïde ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Voie respiratoire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Voie sexuelle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Voie féco-orale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Piqûre de moustique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Voie féco-orale\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La fièvre typhoïde est une maladie du péril fécal (« maladie des mains sales ») : transmission directe par les mains souillées et indirecte par l’eau et les aliments souillés, donc féco-orale.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Fièvre typhoïde – Mode de contamination.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est l'agent causal de la coqueluche ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Streptococcus pneumoniae\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Bordetella pertussis\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Haemophilus influenzae\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Neisseria meningitidis\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Bordetella pertussis\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L’agent de la coqueluche est le bacille de Bordet-Gengou, coccobacille Gram négatif appelé Bordetella pertussis. Haemophilus influenzae et le pneumocoque sont des germes de surinfection.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Coqueluche – II. Étiopathologie ; Cours de maladies infectieuses – Soins infirmiers en maladies infectieuses, Coqueluche.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__6\",\n       \"num\": \"7\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lequel de ces médicaments est contre-indiqué dans le traitement médical de la dengue ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Paracétamol\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"SRO\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Aspirine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Antibiotique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Aspirine\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La prise en charge est symptomatique (paracétamol, hydratation, SRO). L’aspirine est formellement contre-indiquée, de même que les AINS, à cause du risque hémorragique.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), La Dengue – V. Prise en charge des cas.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__7\",\n       \"num\": \"8\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Relevez trois facteurs favorisant la transmission de la fièvre typhoïde parmi les suivants.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Consommation d'eau souillée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rhinorrhée initiale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Mauvaise hygiène des mains\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Consommation d'aliment non cuit\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Assainissement insuffisant\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Consommation d'eau souillée ; C. Mauvaise hygiène des mains ; E. Assainissement insuffisant\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"La fièvre typhoïde est favorisée par le péril fécal : eau de boisson souillée, mains sales (mauvaise hygiène des mains) et assainissement insuffisant (latrines, assainissement du milieu). La rhinorrhée n’a aucun rôle. Remarque : les aliments crus souillés interviennent aussi (le cours conseille de laver les fruits et légumes consommés crus), mais la question n’attend que trois réponses.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Fièvre typhoïde – Mode de contamination, facteurs favorisants et prophylaxie collective.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__8\",\n       \"num\": \"9\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquez quatre complications possibles de la coqueluche chez le nourrisson.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Apnée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Vomissements permanents\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pneumonie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Convulsions\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Raideur de la nuque\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Encéphalopathie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Apnée ; C. Pneumonie ; D. Convulsions ; F. Encéphalopathie\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Chez le nourrisson la coqueluche est grave : apnées syncopales avec arrêt cardio-respiratoire, broncho-pneumopathie de surinfection, complications neurologiques liées à la toxine et à l’anoxie (convulsions, encéphalite/encéphalopathie). La raideur de la nuque n’en fait pas partie. Remarque : les vomissements abondants sont cités dans la forme du nourrisson (cause de dénutrition), mais comme signe et non comme complication retenue.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Coqueluche – 3.2 Forme du nourrisson et IV. Complications.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Relevez quatre signes cliniques évocateurs de la dengue.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Fièvre élevée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Position en chien de fusil\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Céphalées\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Douleurs rétro-orbitaires\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Raideur de la nuque\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Myalgies/arthralgies\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Fièvre élevée ; C. Céphalées ; D. Douleurs rétro-orbitaires ; F. Myalgies/arthralgies\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"La définition du cas suspect de dengue associe une fièvre et au moins deux manifestations parmi : maux de tête, douleur rétro-orbitaire, myalgies, arthralgies, rougeurs, hémorragies. La position en chien de fusil et la raideur de la nuque évoquent une méningite.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), La Dengue – III. Définition standardisée des cas ; Cours de maladies infectieuses – Soins infirmiers en maladies infectieuses, Dengue fébrile.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Relevez quatre actions infirmières de surveillance chez un patient atteint de dengue.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Surveillance de la température\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Surveillance du poids par pesée hebdomadaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Surveillance de la pression artérielle\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Surveillance des selles\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Surveillance de la diurèse\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Surveillance des saignements\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Surveillance de la température ; C. Surveillance de la pression artérielle ; E. Surveillance de la diurèse ; F. Surveillance des saignements\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"La surveillance vise à dépister la fièvre, le choc (pression artérielle, pouls), l’hypovolémie (diurèse) et les hémorragies. La pesée hebdomadaire et la surveillance des selles ne sont pas prioritaires dans la dengue.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), La Dengue – formes hémorragiques et avec syndrome de choc (explication partiellement hors cours du projet).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"À la phase d'état (deuxième septénaire) de la fièvre typhoïde, quelle est la caractéristique des selles diarrhéiques ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Liquides, fétides, avec un aspect de jus de papaye ou de melon\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Afécales, glaireuses et mucopurulentes, parfois sanguinolentes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Abondantes, aqueuses, fécales, en jet, avec un aspect riziforme\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Pâteuses ou liquides, non sanglantes, température normale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Liquides, fétides, avec un aspect de jus de papaye ou de melon\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Au 2e septénaire, la diarrhée est faite de selles liquides, fétides, d’aspect « jus de papaye » (ou melon). B décrit le syndrome dysentérique, C la diarrhée du choléra (riziforme).\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Fièvre typhoïde – 2.3 Phase d’état ; Cours de maladies infectieuses – Soins infirmiers en maladies infectieuses, Choléra – Phase d’état.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelles sont les deux phases de déroulement de l'ascaridiose symptomatique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La phase d'incubation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La phase d'invasion\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La phase de complications\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La phase d'état\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La phase des séquelles\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. La phase d'invasion ; D. La phase d'état\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"L’ascaridiose symptomatique évolue en deux phases : une phase d’invasion (migration larvaire, syndrome de Löffler pulmonaire : toux, fièvre, dyspnée asthmatiforme) puis une phase d’état dominée par les troubles digestifs (douleurs, nausées, diarrhée ou constipation).\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), L’ascaridiose – Manifestations cliniques (la notion de « deux phases » est une connaissance générale).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La symptomatologie en rhumatologie comporte quatre symptômes principaux. Cochez les deux éléments qui ne sont pas des symptômes fondamentaux.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La douleur\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La claudication\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'arthrose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'instabilité\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La scoliose\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"La raideur\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. L'arthrose ; F. La raideur\",\n       \"answerLetters\": [\n        \"C\",\n        \"F\"\n       ],\n       \"explanation\": \"Les signes fondamentaux en rhumatologie sont des symptômes (douleur, instabilité, claudication…). L’arthrose est une maladie et non un symptôme, ce qui explique qu’elle soit à cocher. La correction nationale retient aussi « la raideur » comme non fondamentale. (explication hors cours du projet) Remarque : aucun cours du projet ne traite cette liste. En connaissance générale, la raideur est souvent comptée parmi les symptômes fondamentaux, et la scoliose (une déformation) aurait plutôt été attendue comme intrus. Coche reprise sans changement ; à faire confirmer.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le syndrome dysentérique comprend les caractéristiques suivantes, sauf une. Laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Des douleurs abdominales violentes avec épreintes, ténesmes et faux besoins\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une diarrhée afécale, glaireuse et mucopurulente, parfois sanglante\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Des vomissements incoercibles et fréquents\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une altération de l'état général, de la fièvre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Des vomissements incoercibles et fréquents\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le syndrome dysentérique associe : douleurs abdominales violentes avec épreintes, ténesmes et faux besoins ; selles afécales, glaireuses, mucopurulentes, parfois sanglantes ; altération de l’état général et fièvre. Les vomissements incoercibles ne font pas partie de sa définition. Remarque : dans la shigellose, le même cours cite des vomissements avec pertes hydro-électrolytiques, mais pas comme élément du syndrome dysentérique lui-même.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Les syndromes dysentériques ; Amibiase intestinale – forme aiguë.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les facteurs dont dépend le pouvoir pathogène des agents infectieux, relevez les deux propositions fausses.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La virulence\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La toxicité\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le pouvoir anticorps\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La sécrétion d'enzymes\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La phagocytose\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Le pouvoir antigénique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Le pouvoir anticorps ; E. La phagocytose\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Le pouvoir pathogène dépend de quatre facteurs : la virulence, la toxicité, la sécrétion d’enzymes et le pouvoir antigénique. Le « pouvoir anticorps » n’existe pas et la phagocytose est un moyen de défense de l’hôte (la virulence est justement la capacité à y résister).\\n\\nSource : Cours de maladies infectieuses – Soins infirmiers en maladies infectieuses, Généralités – 3.2 Pouvoir pathogène ; Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Généralités sur les maladies infectieuses.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"À quelle température doit être l'eau utilisée pour la toilette quotidienne des pieds diabétiques ? Cochez une réponse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"34 à 36 °C (bain froid)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"36 à 37 °C (bain normal)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"39 à 45 °C (bain-marie)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 36 à 37 °C (bain normal)\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le pied diabétique est souvent insensible (neuropathie) : l’eau trop chaude expose à des brûlures non ressenties. La toilette quotidienne se fait à l’eau tiède (environ 36–37 °C, vérifiée au coude ou au thermomètre), puis séchage soigneux entre les orteils. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les deux grands facteurs favorisant l'apparition du pied diabétique sont constitués par l'atteinte de quelles structures ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Artères\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Tissus mous\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Nerfs\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Veines\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Vaisseaux lymphatiques\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Artères ; C. Nerfs\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Les deux grands facteurs du pied diabétique sont la neuropathie (atteinte des nerfs : perte de sensibilité, plaies non ressenties) et l’artériopathie (atteinte des artères : ischémie, mauvaise cicatrisation). Les veines et les lymphatiques ne sont pas en cause.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), AOMI (le diabète est un facteur de risque) ; définition du pied diabétique (question 26) – explication partiellement hors cours du projet.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le syndrome cobraïque apparaît entre 30 minutes et une heure après la morsure. Relevez quatre manifestations parmi les suivantes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Des paresthésies et fasciculations\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un syndrome muscarinique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Des épistaxis, une hématurie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un ptosis pathognomonique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Atteinte des nerfs crâniens\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Une hémoptysie, une hématémèse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Des paresthésies et fasciculations ; B. Un syndrome muscarinique ; D. Un ptosis pathognomonique ; E. Atteinte des nerfs crâniens\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Le syndrome cobraïque (élapidés : Naja, Dendroaspis) est neurotoxique : paresthésies et fasciculations, signes muscariniques (hypersialorrhée, sueurs, larmoiement, myosis), ptosis palpébral caractéristique, atteinte des nerfs crâniens (vue, ouïe, déglutition anormales, dysphagie). Épistaxis, hématurie, hémoptysie et hématémèse relèvent du syndrome vipérin (troubles de la coagulation).\\n\\nSource : Cours de venimologie générale (Dr Allali / Dr Akaffou), II.4.1 Troubles neurotoxiques et Tableau II (gradation) ; Envenimations – Traitement (diaporama), Envenimation neurotoxique.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant le test du garrot dans la dengue, quelle affirmation est correcte ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Il permet de confirmer à lui seul le diagnostic de dengue\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il recherche une fragilité capillaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Il est toujours négatif dans la dengue sévère\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Il remplace la numération plaquettaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Il recherche une fragilité capillaire\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le test du garrot (ou du tourniquet) recherche une fragilité capillaire : le brassard est gonflé 5 minutes entre les pressions systolique et diastolique, puis on compte les pétéchies (positif si plus de 20 pétéchies sur 6,25 cm²). Il ne confirme pas seul le diagnostic et ne remplace pas la numération plaquettaire.\\n\\nSource : Cours de maladies infectieuses – Soins infirmiers en maladies infectieuses, Dengue fébrile hémorragique – test du tourniquet.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant un ictère important et une atteinte hépatique, une fièvre jaune doit impérativement être éliminée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La fièvre jaune associe, à la phase jaune, un ictère franc et une atteinte hépato-rénale avec hémorragies. Devant un ictère important avec atteinte hépatique en zone d’endémie, elle doit donc être recherchée (maladie à notification immédiate).\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), La fièvre jaune – III. Données cliniques ; Cours de maladies infectieuses – Soins infirmiers en maladies infectieuses, Fièvre jaune – phase jaune.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le paludisme, la transmission directe du germe de la femme enceinte infectée à son enfant par voie transplacentaire ou par transfusion sanguine n'est pas le seul cas de contamination interhumaine.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale retient « Faux » : en dehors de la piqûre de l’anophèle femelle, la transmission directe d’homme à homme ne se fait que par voie transplacentaire (mère-enfant) ou par transfusion (paludisme d’inoculation). Ce sont les seuls cas de contamination interhumaine.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Paludisme – définition et 5-3 Paludisme d’inoculation (paludisme transfusionnel) ; Documents de révision L3 Médecine, Paludisme (transmission placentaire).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lorsque la femme enceinte est sous prophylaxie antianémique par acide folique et fer, on suspendra le traitement antianémique et on le reprendra 15 jours après la prise de SP.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Chez la femme enceinte sous prophylaxie antianémique (acide folique + fer), on suspend ce traitement lors de la prise de SP et on le reprend 15 jours après la prise de SP.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Paludisme – VIII. Traitement préventif (TPI), NB.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"[…] pour atteindre 39 à 40 °C à la fin du premier septénaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Au 1er septénaire de la fièvre typhoïde, la température monte progressivement (fièvre à oscillations ascendantes, « en échelle ») pour atteindre 39 à 40 °C en fin de septénaire, avant le plateau du 2e septénaire. Remarque : l’énoncé est tronqué dans le sujet (seule la fin « …pour atteindre 39 à 40 °C à la fin du premier septénaire » est visible).\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Fièvre typhoïde – 2.2 Phase d’invasion (CIVET) et 2.3 Fièvre en plateau.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"À la phase d'état, la diarrhée fétide, classiquement dite « jus de melon ou de papaye », peut être remplacée par une constipation.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"À la phase d’état, la diarrhée « jus de melon ou de papaye » est typique, mais elle est inconstante et peut être remplacée par une constipation.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Fièvre typhoïde – 2.3 Phase d’état ; Documents de révision L3 Médecine, QCD Fièvre typhoïde n° 18 (constipation) – nuance de connaissance générale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On appelle pied diabétique toute infection, ulcération ou destruction des tissus profonds du pied associée à une neuropathie et/ou à une artériopathie périphérique des membres inférieurs chez le diabétique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"C’est la définition du pied diabétique : infection, ulcération ou destruction des tissus profonds du pied, associée à une neuropathie et/ou à une artériopathie périphérique des membres inférieurs chez le diabétique. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Schistosoma mansoni est responsable d'une bilharziose urinaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Schistosoma mansoni donne une bilharziose intestinale et hépatosplénique. La bilharziose urinaire est due à Schistosoma haematobium (hématurie terminale).\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Les bilharzioses – 2-3 Phase d’état.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'amibiase est une maladie strictement humaine due à un protozoaire rhizopode appelé Entamoeba histolytica.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L’amibiase est une protozoonose due à Entamoeba histolytica ; l’homme en est l’unique réservoir (maladie strictement humaine). L’amibe est un protozoaire rhizopode (se déplaçant par pseudopodes).\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), L’amibiase – I. Généralités et II. Épidémiologie.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le tétanos, le trismus désigne une contracture des muscles masticateurs bloquant l'ouverture de la bouche. Ce signe s'observe à partir de la phase d'état.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le trismus (contracture des masticateurs bloquant l’ouverture de la bouche) est le signe de l’invasion : il apparaît dès cette phase (environ 48 h) et persiste à la phase d’état. Dire qu’il apparaît « à partir de la phase d’état » est donc faux.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Tétanos – II. Étude clinique (invasion) ; Cours de maladies infectieuses – Soins infirmiers en maladies infectieuses, Tétanos.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la crise du tétanos, l'opisthotonos est décrit par le rachis fixé en hyperextension, avec la tête rejetée en arrière et une hyperlordose lombaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"À la phase d’état, la contracture généralisée fixe le rachis en hyperextension, tête rejetée en arrière, avec hyperlordose lombaire : c’est l’opisthotonos.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Tétanos – Phase d’état ; Cours de maladies infectieuses – Soins infirmiers en maladies infectieuses, Tétanos.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'infection à VIH a un profil épidémiologique qui touche davantage les enfants.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L’infection à VIH touche surtout les adultes jeunes sexuellement actifs (15–49 ans), car la voie sexuelle est le mode de transmission le plus courant. Les enfants sont surtout atteints par transmission mère-enfant.\\n\\nSource : Documents de révision L3 Médecine, VIH/SIDA QCD n° 34 (voie sexuelle) – explication partiellement hors cours du projet.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le terme « OEV » s'applique à tout âge allant de 9 à 21 ans.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le terme OEV (orphelins et enfants rendus vulnérables) concerne les enfants de 0 à 17 ans (moins de 18 ans), pas une tranche « 9 à 21 ans ». (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la bilharziose, chez l'homme, les œufs contenant des miracidiums sont éliminés dans l'eau par les excréments ou les urines.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L’homme infesté rejette les œufs avec ses selles (S. mansoni) ou ses urines (S. haematobium). Dans l’eau douce, les œufs éclosent et libèrent le miracidium, larve ciliée qui gagne le mollusque hôte intermédiaire.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Les bilharzioses – Mode de contamination et Diagnostic (œufs dans les excrétas).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le soin du mal perforant plantaire consiste en un lavage chirurgical de la plaie jusqu'à l'os et à l'articulation.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le mal perforant plantaire est un ulcère profond du pied (diabète, lèpre). Son soin repose sur la mise en décharge et un parage (lavage, débridement) de la plaie jusqu’aux tissus sains, y compris en profondeur vers l’os et l’articulation, souvent chirurgical. (explication hors cours du projet ; le mal perforant plantaire est cité comme complication de la lèpre dans le cours Pathologies tropicales)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'envenimation neurotoxique est le fait du cobra non cracheur.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L’envenimation neurotoxique (cobraïque) est due aux élapidés : Naja (cobras) et Dendroaspis (mambas). Le venin des cobras non cracheurs (ex. Naja melanoleuca) est surtout fait de neurotoxines ; celui du cobra cracheur (Naja nigricollis) provoque plutôt une nécrose.\\n\\nSource : Cours de venimologie générale (Dr Allali / Dr Akaffou), Tableau I (envenimation cobraïque) et II.4.1 ; Exercice 1, V-1.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les venins de serpents ont un double mécanisme d'action : l'immobilisation rapide de la proie et la digestion complète.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les venins de serpents ont un double mécanisme d’action : l’immobilisation rapide de la proie et la prédigestion (et non la digestion complète).\\n\\nSource : Envenimations – Traitement (diaporama), Composition des venins (1) ; Cours de venimologie générale (Dr Allali / Dr Akaffou), Exercice 3, question 1.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la gradation des troubles neurologiques, le grade 2 est caractérisé par une « détresse respiratoire, communication impossible ».\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans la gradation, les troubles neurologiques de grade 2 sont : sueurs et salive abondantes, vomissements, myosis. « Détresse respiratoire, communication impossible » correspond au grade 4.\\n\\nSource : Cours de venimologie générale (Dr Allali / Dr Akaffou), Tableau II – Évaluation clinique de la gravité d’une envenimation.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__37\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’agent pathogène de la syphilis est le tréponêma pertem.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L’agent de la syphilis est Treponema pallidum (tréponème pâle). Treponema pertenue est l’agent du pian.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Les tréponématoses – Syphilis vénérienne (définition) et Le pian (définition).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__38\",\n       \"num\": \"39\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 L’élève Adompo, âgé de 16 ans, a une aventure sexuelle avec une jeune fille pendant les vacances scolaires. Il consulte dans votre centre pour des brûlures mictionnelles accompagnées d’une dysurie et d’une plaie au niveau du pénis.\",\n       \"text\": \"Quelles sont les complications possibles encourues par Adompo si sa prise en charge n'est pas assurée ? Deux réponses sont attendues.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Imperméabilité tubaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Orchi-épididymite\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Cancer précoce des organes atteints\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rétrécissement de l'urètre\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Accouchement prématuré de la partenaire infectée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Orchi-épididymite ; D. Rétrécissement de l'urètre\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Chez l’homme, une urétrite (gonocoque, chlamydia) non traitée peut se compliquer d’orchi-épididymite et, à distance, de rétrécissement de l’urètre. L’imperméabilité tubaire concerne la femme ; l’accouchement prématuré concerne la partenaire et non Adompo. (explication partiellement hors cours du projet ; approche syndromique des IST)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 L’élève Adompo, âgé de 16 ans, a une aventure sexuelle avec une jeune fille pendant les vacances scolaires. Il consulte dans votre centre pour des brûlures mictionnelles accompagnées d’une dysurie et d’une plaie au niveau du pénis.\",\n       \"text\": \"Quelles sont les étapes d'une bonne prise en charge ? À partir des sept étapes ci-dessous, cochez l'ordre correct. (1) Enregistrement des cas/notification ; (2) Notification au(x) partenaire(s) ; (3) Entretien/conseil (counseling) ; (4) Traitement ; (5) Diagnostic syndromique ; (6) Examen physique ; (7) Accueil et interrogatoire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1-2-3-4-5-6-7\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1-2-4-5-6-7-3\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1-2-5-6-7-3-4\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1-2-6-7-3-4-5\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"7-6-5-4-3-2-1\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. 7-6-5-4-3-2-1\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"La prise en charge suit l’ordre : accueil et interrogatoire (7), examen physique (6), diagnostic syndromique (5), traitement (4), entretien/conseil (3), notification au(x) partenaire(s) (2), enregistrement des cas (1), soit 7-6-5-4-3-2-1.\\n\\nSource : Documents de révision L3 Médecine, VIH/SIDA QCD n° 19 (approches de prise en charge des IST) – ordre des étapes : explication partiellement hors cours du projet.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 L’élève Adompo, âgé de 16 ans, a une aventure sexuelle avec une jeune fille pendant les vacances scolaires. Il consulte dans votre centre pour des brûlures mictionnelles accompagnées d’une dysurie et d’une plaie au niveau du pénis.\",\n       \"text\": \"Parmi les diagnostics syndromiques suivants, lesquels peuvent s'appliquer au cas d'Adompo ? Deux réponses sont attendues.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Syndromes d'écoulement urétral et/ou anorectal masculin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Syndromes d'écoulement vaginal et/ou anorectal chez la femme\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Syndromes de douleurs testiculaires\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Syndromes d'ulcérations génitales et/ou bubon\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Syndromes de douleurs abdominales basses chez la femme\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Syndromes de végétations vénériennes ou condylome\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Syndromes d'écoulement urétral et/ou anorectal masculin ; D. Syndromes d'ulcérations génitales et/ou bubon\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"Les brûlures mictionnelles avec dysurie chez l’homme relèvent du syndrome d’écoulement urétral ; la plaie du pénis relève du syndrome d’ulcération génitale (± bubon). Les syndromes « chez la femme » ne s’appliquent pas à Adompo. (explication partiellement hors cours du projet ; approche syndromique des IST)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 Vous êtes de garde à l’EPHD d’Agboville. Vous recevez, avec le médecin, M. Wèssèbian, vendeur et consommateur de noix de cola. Il présente une douleur rétrosternale apparaissant à l’effort et cédant en quelques minutes à l’arrêt de l’effort. Cette douleur irradie typiquement vers la mâchoire inférieure et le bras gauche ; elle est constrictive, en étau, et dure entre 1 et 3 minutes. Constantes : température 36,8 °C ; poids 62 kg ; IMC estimé à 28 kg/m² ; pouls 88 pulsations/min ; fréquence respiratoire 31 cycles/min ; pression artérielle 172/101 mmHg (même valeur après plus de trois prises). L’entretien révèle des antécédents de tabagisme notoire et une consommation habituelle de noix de cola, occasionnant une haleine fétide et des dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence, qui fait cesser la crise. Une sonde urinaire est posée. Le lendemain, la diurèse est de 555 mL.\",\n       \"text\": \"Quel est le diagnostic de M. Wèssèbian retenu par le médecin ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Infarctus du myocarde\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Angine de poitrine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Crise d'OAP\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"AVC\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Angine de poitrine\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Douleur rétrosternale constrictive « en étau », déclenchée par l’effort, cédant à l’arrêt de l’effort et à la trinitrine en 1 à 2 minutes, irradiant vers la mâchoire et le bras gauche : c’est l’angine de poitrine (angor d’effort). Dans l’infarctus, la douleur persiste malgré l’arrêt de l’effort et les dérivés nitrés.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), A. L’angine de poitrine (définition, diagnostic clinique) et B. Syndrome coronarien aigu.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__42\",\n       \"num\": \"43\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 Vous êtes de garde à l’EPHD d’Agboville. Vous recevez, avec le médecin, M. Wèssèbian, vendeur et consommateur de noix de cola. Il présente une douleur rétrosternale apparaissant à l’effort et cédant en quelques minutes à l’arrêt de l’effort. Cette douleur irradie typiquement vers la mâchoire inférieure et le bras gauche ; elle est constrictive, en étau, et dure entre 1 et 3 minutes. Constantes : température 36,8 °C ; poids 62 kg ; IMC estimé à 28 kg/m² ; pouls 88 pulsations/min ; fréquence respiratoire 31 cycles/min ; pression artérielle 172/101 mmHg (même valeur après plus de trois prises). L’entretien révèle des antécédents de tabagisme notoire et une consommation habituelle de noix de cola, occasionnant une haleine fétide et des dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence, qui fait cesser la crise. Une sonde urinaire est posée. Le lendemain, la diurèse est de 555 mL.\",\n       \"text\": \"Parmi les mesures du traitement hygiénodiététique suivantes, retrouvez l'intrus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Régime hyposodé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Repos et sédentarité\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Régime hypolipidique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Sevrage de la consommation d'alcool et du tabac\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Repos et sédentarité\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les mesures hygiéno-diététiques corrigent les facteurs de risque : réduction du sel, réduction des graisses, arrêt du tabac et de l’alcool, pratique du sport. La sédentarité est un facteur de risque : « repos et sédentarité » est donc l’intrus.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Angine de poitrine – 4. Facteurs de risque et 9.4 Traitement préventif.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__43\",\n       \"num\": \"44\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 Vous êtes de garde à l’EPHD d’Agboville. Vous recevez, avec le médecin, M. Wèssèbian, vendeur et consommateur de noix de cola. Il présente une douleur rétrosternale apparaissant à l’effort et cédant en quelques minutes à l’arrêt de l’effort. Cette douleur irradie typiquement vers la mâchoire inférieure et le bras gauche ; elle est constrictive, en étau, et dure entre 1 et 3 minutes. Constantes : température 36,8 °C ; poids 62 kg ; IMC estimé à 28 kg/m² ; pouls 88 pulsations/min ; fréquence respiratoire 31 cycles/min ; pression artérielle 172/101 mmHg (même valeur après plus de trois prises). L’entretien révèle des antécédents de tabagisme notoire et une consommation habituelle de noix de cola, occasionnant une haleine fétide et des dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence, qui fait cesser la crise. Une sonde urinaire est posée. Le lendemain, la diurèse est de 555 mL.\",\n       \"text\": \"Sur quoi porteront vos initiatives d'éducation thérapeutique ? Cochez l'intrus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Expliquer les effets secondaires probables des médicaments\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Expliquer l'importance du suivi des règles hygiéno-diététiques\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Expliquer au patient que le traitement est à vie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Expliquer au patient les effets néfastes de ses habitudes de vie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Expliquer au patient que le traitement est à vie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L’éducation thérapeutique porte sur les effets secondaires des médicaments, le respect des règles hygiéno-diététiques et l’abandon des habitudes néfastes (tabac, cola, sel). La correction nationale retient comme intrus « expliquer que le traitement est à vie ». (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__44\",\n       \"num\": \"45\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 Vous êtes de garde à l’EPHD d’Agboville. Vous recevez, avec le médecin, M. Wèssèbian, vendeur et consommateur de noix de cola. Il présente une douleur rétrosternale apparaissant à l’effort et cédant en quelques minutes à l’arrêt de l’effort. Cette douleur irradie typiquement vers la mâchoire inférieure et le bras gauche ; elle est constrictive, en étau, et dure entre 1 et 3 minutes. Constantes : température 36,8 °C ; poids 62 kg ; IMC estimé à 28 kg/m² ; pouls 88 pulsations/min ; fréquence respiratoire 31 cycles/min ; pression artérielle 172/101 mmHg (même valeur après plus de trois prises). L’entretien révèle des antécédents de tabagisme notoire et une consommation habituelle de noix de cola, occasionnant une haleine fétide et des dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence, qui fait cesser la crise. Une sonde urinaire est posée. Le lendemain, la diurèse est de 555 mL.\",\n       \"text\": \"Quelle est la taille du patient parmi les valeurs suivantes ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"148 cm\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"146 cm\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"144 cm\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 148 cm\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"IMC = poids / taille², donc taille = √(poids / IMC) = √(62 / 28) = √2,214 ≈ 1,488 m, soit 148 cm.\\n\\nSource : calcul à partir des données du cas.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__45\",\n       \"num\": \"46\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 Vous êtes de garde à l’EPHD d’Agboville. Vous recevez, avec le médecin, M. Wèssèbian, vendeur et consommateur de noix de cola. Il présente une douleur rétrosternale apparaissant à l’effort et cédant en quelques minutes à l’arrêt de l’effort. Cette douleur irradie typiquement vers la mâchoire inférieure et le bras gauche ; elle est constrictive, en étau, et dure entre 1 et 3 minutes. Constantes : température 36,8 °C ; poids 62 kg ; IMC estimé à 28 kg/m² ; pouls 88 pulsations/min ; fréquence respiratoire 31 cycles/min ; pression artérielle 172/101 mmHg (même valeur après plus de trois prises). L’entretien révèle des antécédents de tabagisme notoire et une consommation habituelle de noix de cola, occasionnant une haleine fétide et des dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence, qui fait cesser la crise. Une sonde urinaire est posée. Le lendemain, la diurèse est de 555 mL.\",\n       \"text\": \"Au regard de l'IMC, quelle est la classification nutritionnelle du patient ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dénutrition\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Poids normal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Surpoids\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Obésité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Surpoids\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Un IMC de 28 kg/m² se situe entre 25 et 29,9 : c’est un surpoids (obésité à partir de 30).\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020) (surpoids comme facteur de risque) ; classification OMS de l’IMC (explication partiellement hors cours du projet).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__46\",\n       \"num\": \"47\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 Vous êtes de garde à l’EPHD d’Agboville. Vous recevez, avec le médecin, M. Wèssèbian, vendeur et consommateur de noix de cola. Il présente une douleur rétrosternale apparaissant à l’effort et cédant en quelques minutes à l’arrêt de l’effort. Cette douleur irradie typiquement vers la mâchoire inférieure et le bras gauche ; elle est constrictive, en étau, et dure entre 1 et 3 minutes. Constantes : température 36,8 °C ; poids 62 kg ; IMC estimé à 28 kg/m² ; pouls 88 pulsations/min ; fréquence respiratoire 31 cycles/min ; pression artérielle 172/101 mmHg (même valeur après plus de trois prises). L’entretien révèle des antécédents de tabagisme notoire et une consommation habituelle de noix de cola, occasionnant une haleine fétide et des dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence, qui fait cesser la crise. Une sonde urinaire est posée. Le lendemain, la diurèse est de 555 mL.\",\n       \"text\": \"Que traduit la diurèse du patient ? Cochez une réponse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Anurie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Oligurie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Polyurie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Pollakiurie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Oligurie\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Une diurèse basse traduit une oligurie (diminution du volume des urines), contrairement à l’anurie (quasi absence d’urines), à la polyurie (urines abondantes) et à la pollakiurie (mictions fréquentes). Remarque : selon le seuil du cours (oligurie < 500 mL/24 h), une diurèse de 555 mL n’est pas strictement une oligurie ; l’oligurie reste toutefois la seule proposition cohérente parmi les quatre.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Insuffisance rénale aiguë – physiopathologie (oligurie < 500 mL/24 h ; anurie ≈ 50 mL).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__47\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour accompagner un patient en phase terminale de vie, le médecin prescrit une perfusion de 1 litre de Ringer lactate en 24 heures. Calculez le débit de la perfusion et cochez la réponse exacte.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"14 gouttes/min\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"13 gouttes/min\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"12 gouttes/min\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 14 gouttes/min\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Débit (gouttes/min) = volume (mL) × 20 / durée (min) = 1000 × 20 / 1440 = 13,9 ≈ 14 gouttes/min.\\n\\nSource : calcul de débit de perfusion (1 mL = 20 gouttes pour un perfuseur standard).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__48\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une perfusion est maintenue à 20 gouttes par minute pendant 8 heures. Quel volume de soluté est passé pendant ce temps ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"B. 380 mL\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"C. 480 mL\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"D. 580 mL\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. C. 480 mL\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"20 gouttes/min = 1 mL/min (1 mL = 20 gouttes). En 8 h = 480 min, le volume passé est de 480 mL.\\n\\nSource : calcul de débit de perfusion.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__49\",\n       \"num\": \"50\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lors d'une intervention de chirurgie cardiaque, vous devez injecter 3 mg/kg d'héparine à un patient de 58 kg. Vous disposez d'un flacon de 5 mL contenant 25 000 UI (1 mL = 50 mg = 5 000 UI). Quel volume d'héparine devez-vous injecter ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2,90 mL\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"5,80 mL\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3,48 mL\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"12,70 mL\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 3,48 mL\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dose = 3 mg/kg × 58 kg = 174 mg. Avec 1 mL = 50 mg : volume = 174 / 50 = 3,48 mL.\\n\\nSource : calcul de dose à partir des données de l’énoncé.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__50\",\n       \"num\": \"51\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous administrez une perfusion de 500 mL de sérum glucosé à 10 %. Quelle masse de glucose, en grammes, le patient reçoit-il à l'issue de la perfusion ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"75 g\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"50 g\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"25 g\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"12,5 g\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 50 g\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un soluté glucosé à 10 % contient 10 g de glucose pour 100 mL, donc 500 mL apportent 50 g.\\n\\nSource : calcul de concentration.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__51\",\n       \"num\": \"52\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour soulager les crises du patient, le médecin prescrit 35 mg de Risordan® en comprimés. Vous disposez de comprimés dosés à 20 mg. Quelle quantité de comprimés devez-vous préparer ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1 comprimé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1 comprimé + ½ comprimé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1 comprimé + ⅔ de comprimé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1 comprimé + ¾ de comprimé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 1 comprimé + ¾ de comprimé\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"35 mg / 20 mg par comprimé = 1,75 comprimé, soit 1 comprimé + ¾ de comprimé.\\n\\nSource : calcul de dose à partir des données de l’énoncé.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__52\",\n       \"num\": \"53\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le dévouement de l'infirmière au bien-être des personnes confiées à sa garde l'engage à une obligation de quelle nature ? Cochez une réponse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Résultat\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Moyens\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Moyens\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L’infirmière est tenue à une obligation de moyens : elle doit mettre en œuvre tous les soins conformes aux règles de l’art, mais ne peut garantir la guérison (ce qui serait une obligation de résultat). (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__53\",\n       \"num\": \"54\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle proposition correspond à la formulation correcte d'un diagnostic infirmier pour l'affection de M. Wèssèbian ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Syndrome douloureux thoracique relié à une perturbation du débit sanguin coronaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Perturbation du débit sanguin coronaire reliée au syndrome douloureux thoracique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Aucune des deux propositions n'est correcte\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Syndrome douloureux thoracique relié à une perturbation du débit sanguin coronaire\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un diagnostic infirmier se formule « problème relié à (cause/étiologie) ». Le problème est le syndrome douloureux thoracique ; la cause est la perturbation du débit sanguin coronaire, comme dans la définition de l’angine de poitrine.\\n\\nSource : Cours Médecine IDE 2 INFAS (actualisé 2020), Angine de poitrine – 1. Définition ; Documents de révision L3 Médecine, Soins infirmiers (énoncé du diagnostic infirmier : problème + étiologie).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__54\",\n       \"num\": \"55\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Chez un patient atteint de dengue, relevez trois actes de la conduite infirmière immédiate en matière de prévention et de sécurité.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Isolement sous moustiquaire imprégnée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Transmission écrite et orale de toute aggravation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Élimination des gîtes larvaires autour du service\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Alerte immédiate du médecin en cas de choc ou de saignement important\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Éducation du patient et de la famille\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Isolement sous moustiquaire imprégnée ; B. Transmission écrite et orale de toute aggravation ; D. Alerte immédiate du médecin en cas de choc ou de saignement important\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"En urgence, l’infirmier protège et sécurise : isolement du malade sous moustiquaire imprégnée (éviter de nouvelles piqûres et la transmission), transmission écrite et orale de toute aggravation, alerte immédiate du médecin en cas de choc ou de saignement important. L’élimination des gîtes larvaires est une mesure collective et l’éducation n’est pas un acte immédiat.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Dengue et Fièvre jaune (isolement sous moustiquaires imprégnées, lutte antivectorielle) – explication partiellement hors cours du projet.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j10-sf3__55\",\n       \"num\": \"56\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments suivants permettant de distinguer la dengue de la fièvre jaune, relevez uniquement ceux observés dans la dengue.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Douleurs rétro-orbitaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Syndrome hémorragique avec ictère\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Test du garrot positif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Atteinte hépatique prédominante\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Thrombopénie importante\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Hyperbilirubinémie importante\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Douleurs rétro-orbitaires ; C. Test du garrot positif ; E. Thrombopénie importante\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"La dengue se distingue par les douleurs rétro-orbitaires, le test du garrot positif et la thrombopénie importante (pétéchies). L’ictère, l’atteinte hépatique prédominante et l’hyperbilirubinémie orientent vers la fièvre jaune (phase jaune hépato-rénale).\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), La Dengue et La fièvre jaune ; Cours de maladies infectieuses – Soins infirmiers en maladies infectieuses, Dengue fébrile hémorragique (absence d’ictère, thrombocytopénie).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J10_Medecine_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
